/**
 * Verify VPS section WebP assets (see scripts/gen-vps-section-raster-webp.js).
 * Design-owned WebPs are checked only — never generated by gen:vps-section-raster-webp.
 */
const fs = require("fs");
const path = require("path");
const sharp = require("sharp");

/** @type {{ path: string, width: number, height: number, designOwned?: boolean }[]} */
const checks = [
  {
    path: "static/images/bg/vps/keep-your-vps-forever-desktop.webp",
    width: 1440,
    height: 748,
  },
  {
    path: "static/images/bg/vps/keep-your-vps-forever-mobile.webp",
    width: 393,
    height: 1669,
    designOwned: true,
  },
  {
    path: "static/images/vps/hand-desktop.webp",
    width: 123,
    height: 137,
    designOwned: true,
  },
  {
    path: "static/images/vps/hand-mobile.webp",
    width: 135,
    height: 97,
    designOwned: true,
  },
  {
    path: "static/images/vps/oqtima-forex-cfd-dark-desktop.webp",
    width: 242,
    height: 251,
    designOwned: true,
  },
  {
    path: "static/images/vps/oqtima-forex-cfd-dark-mobile.webp",
    width: 242,
    height: 251,
    designOwned: true,
  },
  {
    path: "static/images/vps/oqtima-forex-cfd-light-desktop.webp",
    width: 222,
    height: 230,
  },
  {
    path: "static/images/vps/oqtima-forex-cfd-light-mobile.webp",
    width: 314,
    height: 246,
  },
];

async function main() {
  const root = path.join(__dirname, "..");
  const errors = [];
  for (const { path: rel, width, height, designOwned } of checks) {
    const p = path.join(root, rel);
    if (!fs.existsSync(p)) {
      errors.push(
        designOwned
          ? `Missing ${rel} — design-owned asset; add manually (do not use gen:vps-section-raster-webp)`
          : `Missing ${rel} — run: npm run gen:vps-section-raster-webp`
      );
      continue;
    }
    const meta = await sharp(p).metadata();
    if (meta.width !== width || meta.height !== height) {
      errors.push(
        `${rel}: expected ${width}×${height}, got ${meta.width}×${meta.height}`
      );
    }
  }
  if (errors.length) {
    console.error("verify-vps-section-raster-webp failed:\n");
    errors.forEach((e) => console.error(" ", e));
    process.exit(1);
  }
  console.log("OK: VPS section WebP assets present.");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
